import { AlertTriangle, CheckCircle2, Circle, CircleDot, FileText, Info, Lock } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Container, SectionHeading } from "@/components/ui/container";
import { cn } from "@/lib/utils";

/**
 * Static, clearly labelled illustration of the action-plan format.
 * It is NOT generated by AI and contains no real user data.
 */
type StepStatus = "completed" | "in_progress" | "pending" | "blocked";

const DEMO_STEPS: { title: string; detail: string; status: StepStatus }[] = [
  { title: "Reunir comprovantes", detail: "Nota fiscal, fotos do defeito e conversa com a loja.", status: "completed" },
  { title: "Registrar solicitação formal na loja", detail: "Por escrito, guardando o número de protocolo.", status: "in_progress" },
  { title: "Aguardar o prazo informado pelo fornecedor", detail: "Anotar a data-limite e a resposta recebida.", status: "pending" },
  { title: "Escalar para canal de reclamação", detail: "Se não houver solução no prazo.", status: "pending" },
];

const statusMeta: Record<StepStatus, { label: string; icon: typeof Circle; className: string }> = {
  completed: { label: "Concluído", icon: CheckCircle2, className: "text-success" },
  in_progress: { label: "Em andamento", icon: CircleDot, className: "text-primary" },
  pending: { label: "Pendente", icon: Circle, className: "text-muted-foreground" },
  blocked: { label: "Bloqueado", icon: AlertTriangle, className: "text-danger" },
};

export function DemoPreview() {
  const done = DEMO_STEPS.filter((s) => s.status === "completed").length;
  const progress = Math.round((done / DEMO_STEPS.length) * 100);

  return (
    <section id="demonstracao" className="scroll-mt-20 border-y bg-muted/40 py-20 sm:py-28">
      <Container className="grid items-center gap-12 lg:grid-cols-[1fr_1.2fr]">
        <div>
          <SectionHeading
            eyebrow="Demonstração"
            title="Do relato confuso a um plano que você consegue seguir"
            description="Veja o formato de um plano de resolução. Cada passo tem status, checklist e espaço para suas anotações — e o plano separa fatos, suposições e recomendações."
          />
          <ul className="mt-8 space-y-3 text-sm">
            {[
              "Fatos informados por você ficam separados das suposições da IA",
              "Informações que faltam aparecem destacadas",
              "Próxima ação sempre clara no topo",
            ].map((t) => (
              <li key={t} className="flex gap-2.5 text-muted-foreground">
                <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-primary" />
                {t}
              </li>
            ))}
          </ul>
        </div>

        <figure className="relative">
          <figcaption className="mb-3 flex items-center gap-1.5 text-xs text-muted-foreground">
            <Info className="h-3.5 w-3.5" />
            Exemplo ilustrativo do formato — não gerado por IA nem baseado em dados reais.
          </figcaption>
          <div className="overflow-hidden rounded-2xl border bg-card shadow-2xl shadow-black/[0.06] dark:shadow-black/40">
            <div className="flex items-center gap-1.5 border-b px-4 py-3">
              <span className="h-2.5 w-2.5 rounded-full bg-border" />
              <span className="h-2.5 w-2.5 rounded-full bg-border" />
              <span className="h-2.5 w-2.5 rounded-full bg-border" />
              <span className="ml-3 inline-flex items-center gap-1 text-xs text-muted-foreground">
                <Lock className="h-3 w-3" /> resolve.ai/problemas/exemplo
              </span>
            </div>

            <div className="p-5 sm:p-6">
              <div className="flex flex-wrap items-center gap-2">
                <Badge tone="primary">Garantias e trocas</Badge>
                <Badge tone="warning">Prioridade alta</Badge>
              </div>
              <h3 className="mt-3 text-lg font-semibold">Geladeira com defeito dentro da garantia</h3>
              <p className="mt-1 text-sm text-muted-foreground">
                Objetivo: obter reparo, troca ou devolução do valor pago.
              </p>

              <div className="mt-5">
                <div className="flex justify-between text-xs text-muted-foreground">
                  <span>Progresso</span>
                  <span>{progress}%</span>
                </div>
                <div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-muted">
                  <div className="h-full rounded-full bg-primary" style={{ width: `${progress}%` }} />
                </div>
              </div>

              <div className="mt-5 rounded-xl border border-primary/30 bg-accent/50 p-3.5 text-sm">
                <p className="text-xs font-medium text-accent-foreground">Próxima ação recomendada</p>
                <p className="mt-1">Enviar a solicitação formal à loja e salvar o protocolo.</p>
              </div>

              <ol className="mt-5 space-y-1">
                {DEMO_STEPS.map((step) => {
                  const meta = statusMeta[step.status];
                  return (
                    <li key={step.title} className="flex gap-3 rounded-lg p-2.5 transition-colors hover:bg-muted/60">
                      <meta.icon className={cn("mt-0.5 h-4.5 w-4.5 shrink-0", meta.className)} aria-label={meta.label} />
                      <div className="min-w-0 flex-1">
                        <p className={cn("text-sm font-medium", step.status === "completed" && "text-muted-foreground line-through")}>
                          {step.title}
                        </p>
                        <p className="text-xs text-muted-foreground">{step.detail}</p>
                      </div>
                      <span className="hidden text-xs text-muted-foreground sm:block">{meta.label}</span>
                    </li>
                  );
                })}
              </ol>

              <div className="mt-5 grid gap-3 border-t pt-5 sm:grid-cols-2">
                <div>
                  <p className="text-xs font-medium">Documentos necessários</p>
                  <ul className="mt-1.5 space-y-1 text-xs text-muted-foreground">
                    <li className="flex items-center gap-1.5"><FileText className="h-3 w-3" /> Nota fiscal</li>
                    <li className="flex items-center gap-1.5"><FileText className="h-3 w-3" /> Termo de garantia</li>
                  </ul>
                </div>
                <div>
                  <p className="text-xs font-medium">Informação faltando</p>
                  <p className="mt-1.5 text-xs text-muted-foreground">Data exata da compra e número do pedido.</p>
                </div>
              </div>
            </div>
          </div>
        </figure>
      </Container>
    </section>
  );
}
